package com.yupi.template.modelconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.core.env.Environment;import java.util.*;import com.yupi.template.utils.GsonUtils;
class TaskModelChoiceTest {
 @Test void selectionIsFrozenAndStaleVersionRejected(){var jdbc=mock(JdbcTemplate.class);var service=new ModelSettings(jdbc,mock(ModelVault.class),mock(Environment.class));var spec=new ModelSpec("a".repeat(32),2,"DeepSeek","TEXT","compatible","https://ark.cn-beijing.volces.com/api/v3","model-id",60,2000,"2K","1:1");when(jdbc.queryForList(anyString(),eq(spec.id()))).thenReturn(List.of(Map.of("spec",GsonUtils.toJson(spec))));when(jdbc.update(anyString(),any(),eq("task"))).thenReturn(1);assertThrows(com.yupi.template.exception.BusinessException.class,()->service.chooseTaskText("task",spec.id(),1));verify(jdbc,never()).update(anyString(),any(),any());service.chooseTaskText("task",spec.id(),2);verify(jdbc).update(eq("UPDATE article_text_profile SET spec=? WHERE taskId=?"),eq(GsonUtils.toJson(spec)),eq("task"));}
 @Test void omittedPreservesSnapshotAndUnavailableIsRejected(){var jdbc=mock(JdbcTemplate.class);var service=new ModelSettings(jdbc,mock(ModelVault.class),mock(Environment.class));service.chooseTaskText("task",null,null);verifyNoInteractions(jdbc);assertThrows(com.yupi.template.exception.BusinessException.class,()->service.chooseTaskText("task","unavailable",1));verify(jdbc,never()).update(anyString(),any(),any());}
}
